def url(slug=''):
 return '/' + (slug.strip('/')+'/' if slug else '')

def link(slug,label,cls='',extra=''):
 return f'<a href="{url(slug)}" class="{cls}" {extra}>{label}</a>'

def ext(href,title,cls='text-link'):
 return f'<a class="{cls}" href="{escape(href,quote=True)}" target="_blank" rel="noopener noreferrer">{escape(title)} <span aria-hidden="true">↗</span></a>'

def photo(key,cls='',loading='lazy'):
 p=PHOTOS[key]
 priority=' fetchpriority="high"' if loading=='eager' else ''
 return f'<figure class="photo {cls}"><img src="{escape(p["src"],quote=True)}" alt="{escape(p["name"],quote=True)}" loading="{loading}" decoding="async" referrerpolicy="no-referrer"{priority}/><div class="photo-fallback" role="status">Fotografija trenutno ni dosegljiva. Podatki o viru so navedeni spodaj.</div><figcaption>{escape(p["name"])} · {ext(p["url"],p["author"]+" / "+p["licence"],"source-link")}</figcaption></figure>'

def eyebrow(t):return f'<p class="eyebrow">{escape(t)}</p>'
def hero(kicker,title,lead,side='',cls=''):
 return f'<section class="page-hero {cls}"><div class="wrap page-hero-grid"><div>{eyebrow(kicker)}<h1>{title}</h1><p class="lead">{lead}</p></div>{side or "<div class=\"hero-index\">ZZT / 2026<br>ZNANJE ↔ PRAKSA</div>"}</div></section>'

def band(t): return f'<div class="section-heading">{eyebrow(t)}</div>'
def wrap(section):return f'<div class="wrap">{section}</div>'

def home():
 cards=''.join(f'''<article class="visual-project"><div class="visual-project-media">{photo(p["photo"],"tile-photo")}</div><div class="visual-project-body"><p class="status">{escape(p["status"])} / {escape(p["tag"])}</p><h3><a href="/projekti/{p['slug']}/">{escape(p['title'])}</a></h3><p>{escape(p["subtitle"])}</p><a href="/projekti/{p['slug']}/" class="text-link">Preberite projektno zasnovo <span aria-hidden="true">↗</span></a></div></article>''' for p in PROJ)
 return f'''<section class="front-hero">{photo('kolpa_kuzelj','front-hero-photo','eager')}<div class="front-overlay" aria-hidden="true"></div><div class="wrap front-content"><p class="eyebrow">ZZT / ZAVOD ZA ZELENO TEHNOLOGIJO · KOSTEL</p><h1>Razumeti okolje. <em>Razvijati uporabne rešitve.</em></h1><p class="front-lead">Povezujemo raziskovalne metode, zelene tehnologije in izobraževanje mladih. Od raziskovalnega vprašanja do izobraževalnega gradiva in premišljene projektne zasnove.</p><div class="hero-actions">{link('o-zavodu','Spoznajte zavod <span aria-hidden="true">↗</span>','btn primary')}{link('projekti','Projektni portfelj <span aria-hidden="true">↗</span>','btn hero-ghost')}</div></div><p class="front-photo-note">Reka Kolpa, med Kužljem in Gašparci</p></section>
 <section class="section front-intro"><div class="wrap front-intro-grid"><div class="front-intro-copy">{eyebrow('01 / O zavodu')}<h2>Od znanja do <em>praktične uporabe.</em></h2><p class="big-paragraph">ZZT je slovenski zasebni nepridobitni zavod, ustanovljen leta 2026. Deluje na področjih raziskovanja, zelenih tehnologij, neformalnega izobraževanja in projektnega sodelovanja.</p><p>Vsako novo pobudo začnemo s pregledom raziskav, pogovorom z ljudmi, ki jih zadeva, in izvedljivim načrtom. Metode in rezultate bomo objavljali skupaj z viri.</p>{link('o-zavodu','Uradni podatki in poslanstvo <span aria-hidden="true">↗</span>','text-link')}</div>{photo('kolpa_bosljiva','front-intro-photo')}</div></section>
 <section class="section front-focus"><div class="wrap"><div class="front-section-header">{eyebrow('02 / Področja delovanja')}<h2>Od raziskav do <em>znanja za skupnost.</em></h2></div><div class="front-focus-grid"><a href="/raziskave-in-razvoj/" class="front-focus-item"><span class="front-focus-number">01 / RAZISKOVANJE</span><h3>Okolje in podatki</h3><p>Priprava terenskih protokolov, okoljsko spremljanje, analiza in strokovno preverjanje.</p><span class="front-focus-arrow" aria-hidden="true">↗</span></a><a href="/raziskave-in-razvoj/" class="front-focus-item"><span class="front-focus-number">02 / RAZVOJ</span><h3>Zelene tehnologije</h3><p>Krožno gospodarstvo, učinkovita raba virov in razvoj uporabnih tehnoloških rešitev.</p><span class="front-focus-arrow" aria-hidden="true">↗</span></a><a href="/izobrazevanje-in-mladi/" class="front-focus-item"><span class="front-focus-number">03 / IZOBRAŽEVANJE</span><h3>Mladi in kompetence</h3><p>Učni materiali, mladinsko sodelovanje, digitalne spretnosti in prenos znanja.</p><span class="front-focus-arrow" aria-hidden="true">↗</span></a><a href="/sodelovanje/" class="front-focus-item"><span class="front-focus-number">04 / SODELOVANJE</span><h3>Partnerstva in projekti</h3><p>Priprava prijav, sodelovanje z raziskovalci, učitelji, občinami in evropskimi organizacijami.</p><span class="front-focus-arrow" aria-hidden="true">↗</span></a></div></div></section>
 <section class="section front-projects"><div class="wrap"><div class="front-section-title"><div>{eyebrow('03 / Projekti')}<h2>Projekti <em>v pripravi.</em></h2><p>Predstavljeni so predlogi. Financiranje še ni potrjeno in rezultati niso predstavljeni kot izvedeni.</p></div>{link('projekti','Vsi projekti <span aria-hidden="true">↗</span>','text-link')}</div><div class="visual-project-grid">{cards}</div></div></section>
 <section class="section front-kolpa"><div class="wrap front-kolpa-grid">{photo('kolpa','front-kolpa-photo')}<div>{eyebrow('04 / Prostor in odgovornost')}<h2>Iz Kostela. <em>Odprti za sodelovanje.</em></h2><p>Sedež zavoda je v Kostelu. Območje Kolpe povezuje naravno okolje, lokalno dediščino in vprašanja trajnostnega razvoja, ki jih želimo obravnavati s podatki, strokovnim znanjem in sodelovanjem.</p><p>Prikazane fotografije so posnetki Kolpe iz javnih fotografskih zbirk, ne dokumentacija terenskega dela zavoda.</p>{link('sodelovanje','Predlagajte sodelovanje <span aria-hidden="true">↗</span>','text-link')}</div></div></section>
 <section class="section front-experience"><div class="wrap front-experience-grid"><div>{eyebrow('05 / Ljudje in izkušnje')}<h2>Izkušnje, na katerih <em>gradimo naprej.</em></h2></div><div><p class="big-paragraph">Dan Fredi Grmuša, ustanovitelj in projektna kontaktna oseba, ima izkušnje s pripravo evropskih prijav, mladinskimi projekti in mednarodnim sodelovanjem.</p><div class="reference-strip"><span>DCYDE – koordinacija mladinske skupine</span><span>VIBE – Erasmus+ usposabljanje</span><span>GREENCULTLABS in CARESHIFT – priprava prijav</span></div><p class="note">Navedene reference so osebne izkušnje. Niso zaključeni projekti ZZT.</p>{link('ekipa-in-izkusnje','Preverite vloge in reference <span aria-hidden="true">↗</span>','text-link')}</div></div></section>
 <section class="front-cta"><div class="wrap front-cta-grid"><div>{eyebrow('Kontakt / sodelovanje')}<h2>Povežimo znanje <em>in izvedbo.</em></h2><p>Za projektne pobude, strokovne predloge in izobraževalno sodelovanje.</p></div><a class="btn primary" href="{MAIL}">Pišite: {EMAIL} <span aria-hidden="true">↗</span></a></div></section>'''

def about():
 return hero('O zavodu / ZZT','Zeleni prehod potrebuje <em>dokaze.</em>','Ustanovljeni smo z namenom povezovanja raziskav, zelenih tehnologij in izobraževanja mladih.',photo('kostel','page-hero-photo'))+f'''<section class="section"><div class="wrap two-col">{band('Pravna podlaga')}<div><h2>Nepridobitni zasebni zavod.</h2><p>ZZT – Zavod za zeleno tehnologijo je bil ustanovljen 29. septembra 2026, vpis v sodni register pa je bil opravljen 21. oktobra 2026. Poslanstvo je opredeljeno v ustanovitvenem aktu.</p><p>Temeljni namen je spodbujanje mladih pri razvoju, razumevanju in uporabi novih zelenih tehnologij, trajnostnih rešitev, digitalnih orodij ter zelenih in prihodnostnih kompetenc.</p><p>Pri javni predstavitvi ločujemo dejansko registrirane dejavnosti od rezultatov, ki jih bomo šele ustvarili.</p></div></div></section>
 <section class="section cream-section"><div class="wrap"><div class="section-title-row">{band('Organizacija')}<h2>Dejavnosti po ustanovitvenem aktu</h2></div><div class="facts-grid"><div><h3>Raziskave in razvoj</h3><p>Zelene tehnologije, krožno gospodarstvo, energetska učinkovitost, okoljske inovacije (7. in 8. člen).</p></div><div><h3>Izobraževanje in mladi</h3><p>Neformalno izobraževanje, mentorstvo, delavnice, socialno vključevanje in medgeneracijsko sodelovanje.</p></div><div><h3>Digitalno delo</h3><p>Programska in spletna orodja, založništvo, javne publikacije ter digitalna gradiva.</p></div><div><h3>Mednarodni projekti</h3><p>Priprava, prijava, upravljanje in izvajanje domačih, evropskih ter Erasmus+ projektov.</p></div></div></div></section>
 <section class="section"><div class="wrap two-col">{band('Podatki')}<div><h2>Pravna identiteta</h2><dl class="dl"><div><dt>Naziv</dt><dd>ZZT – Zavod za zeleno tehnologijo</dd></div><div><dt>Območje sedeža</dt><dd>Kostel, Slovenija</dd></div><div><dt>Pravna oblika</dt><dd>Zasebni nepridobitni zavod</dd></div><div><dt>Ustanovitev</dt><dd>September 2026</dd></div><div><dt>Ustanovitelj in projektni kontakt</dt><dd>Dan Fredi Grmuša</dd></div><div><dt>E-pošta</dt><dd><a href="mailto:{EMAIL}">{EMAIL}</a></dd></div></dl><p class="note">Zavod je registriran kot zasebna nepridobitna pravna oseba. Na javni strani ne predstavljamo upravnih oznak, razvojnih idej ali prijav kot dokaz pridobljenega financiranja.</p></div></div></section>'''

def research():
 return hero('Raziskave in razvoj','Raziskovanje kot <em>metoda.</em>','Od raziskovalnega vprašanja do primerljivih podatkov in jasno utemeljenih zaključkov.',photo('ankaran','page-hero-photo'))+f'''<section class="section"><div class="wrap two-col">{band('Pristop')}<div><h2>Ne trdimo več, kot kažejo podatki.</h2><p>Pripravljamo manjše, jasno omejene raziskovalne zasnove. Njihov obseg prilagajamo dejanskim izvajalskim zmogljivostim in smernicam stroke.</p><ol class="method-list"><li><strong>Opredelimo problem</strong><span>Primarni in strokovni viri, raziskovalna vrzel, znane omejitve.</span></li><li><strong>Izberemo metodo</strong><span>Vzorčenje, popisni protokol, etična pravila in merila kakovosti.</span></li><li><strong>Zabeležimo podatke</strong><span>Dokumentirana izvedba, izvor vsake trditve in preverljiva evidenca.</span></li><li><strong>Objavimo rezultate</strong><span>Jasna interpretacija, odprta gradiva, kadar so pravice in pogodbe združljive.</span></li></ol></div></div></section>
 <section class="section cream-section"><div class="wrap"><div class="section-title-row">{band('Aktualno v razvoju')}<h2>Obala v podatkih</h2></div><div class="editorial-pair">{photo('izola','editorial-image')}<div><p class="status">Prijava v pripravi</p><p>Pilot za standardizirano spremljanje vidnih odpadkov na izbranih urbanih obalnih lokacijah. Metodologija se opira na javno dostopne evropske smernice, ne na vnaprej predpostavljene rezultate.</p>{link('projekti/obala-v-podatkih','Raziskovalna zasnova <span aria-hidden="true">↗</span>','text-link')}</div></div></div></section>'''

def education():
 return hero('Izobraževanje in mladi','Znanje, ki ga je mogoče <em>uporabiti.</em>','Praktične kompetence, razumljiva gradiva in sodelovanje mladih pri strokovnih temah.')+f'''<section class="section"><div class="wrap two-col">{band('Učenje')}<div><h2>Od strokovne teme do učnega procesa.</h2><p>Ustanovitveni akt zavodu omogoča neformalno izobraževanje, mentorstvo, delavnice in razvoj digitalnih izobraževalnih gradiv. Naš pristop temelji na primerih, jasnih korakih in vrednotenju pridobljenega znanja.</p><div class="stack-items"><article><h3>Zeleni prehod</h3><p>Krožno gospodarstvo, zmanjševanje odpadkov, okoljsko odločanje in trajnostne navade.</p></article><article><h3>Digitalne kompetence</h3><p>Preverjanje virov, zbiranje podatkov, digitalne publikacije in odgovorna raba orodij.</p></article><article><h3>Projektna pismenost</h3><p>Načrtovanje ciljev, razdelitev nalog, javno sodelovanje in dokumentiranje rezultatov.</p></article></div></div></div></section>
 <section class="section olive-section"><div class="wrap two-col">{band('Izkušnje')}<div><h2>Gradimo na dokazljivem delu.</h2><p>Ustanovitelj ima osebne izkušnje z Erasmus+ usposabljanji, mednarodnimi mladinskimi izmenjavami in dokumentiranjem rezultatov projektov DCYDE. Te izkušnje niso prikazane kot že izvedeni projekti ZZT.</p>{link('ekipa-in-izkusnje','O izvajalski ekipi <span aria-hidden="true">↗</span>','text-link')}</div></div></section>'''

def projects():
 cards=''.join(f'<article class="project-card"><div class="project-card-meta"><span>{escape(p["tag"])}</span><span>{p["year"]}</span></div><p class="status">{escape(p["status"])}</p><h2>{link("projekti/"+p["slug"],escape(p["title"]))}</h2><p>{escape(p["intro"])}</p>{link("projekti/"+p["slug"],"O projektu <span aria-hidden=\"true\">↗</span>","text-link")}</article>' for p in PROJ)
 return hero('Projekti / registrirano stanje','Pripravljamo delo, ki bo <em>preverljivo.</em>','Projektni koncept ni isto kot odobrena sredstva, izveden projekt ali znanstvena objava.')+f'<section class="section"><div class="wrap project-grid">{cards}</div></section><section class="section cream-section"><div class="wrap two-col">{band("Načelo preglednosti")}<div><h2>Status vsakega projekta je javen.</h2><p>Ko bo prijava dejansko oddana, odobrena ali zaključena, bomo status posodobili na podlagi dokumentov. Za zdaj navedene tri pobude ostajajo v razvoju oziroma pripravi prijave.</p></div></div></section>'

def project(p):
 meth=''.join(f'<li>{escape(x)}</li>' for x in p['methods'])
 outcomes=''.join(f'<li>{escape(x)}</li>' for x in p['outcomes'])
 sources=''.join(f'<li>{ext(h,t)}</li>' for t,h in p['sources'])
 return f'''<section class="project-hero"><div class="wrap">{eyebrow('Projektni portfelj / '+p['tag'])}<div class="breadcrumbs">{link('projekti','Projekti')} <span>/</span> {escape(p['title'])}</div><h1>{escape(p['title'])}</h1><p class="lead">{escape(p['subtitle'])}</p><div class="project-labels"><span class="status dark">{escape(p['status'])}</span><span>{escape(p['fund'])}</span><span>Samostojna projektna zasnova</span></div></div></section><section class="section project-story"><div class="wrap story-grid"><aside><p class="eyebrow">Raziskovalna oziroma projektna zasnova</p><div class="sticky-meta"><strong>Stanje</strong><span>{escape(p['status'])}</span><strong>Izvajalec</strong><span>ZZT – predlagani prijavitelj</span><strong>Financiranje</strong><span>Ni potrjeno</span></div></aside><article>{photo(p['photo'],'story-photo')}<h2>Razlog in namen</h2><p class="big-paragraph">{escape(p['intro'])}</p><h2>Predvidena metoda</h2><ol class="content-list">{meth}</ol><h2>Pričakovani izdelki</h2><ul class="content-list">{outcomes}</ul><p class="note">Vsi navedeni izdelki so cilji projekta, ne že doseženi rezultati.</p><h2>Osnovni viri</h2><ul class="source-list">{sources}</ul></article></div></section><section class="section olive-section"><div class="wrap"><div class="section-title-row">{band('Kontakt')}<h2>Strokovno sodelovanje pri projektu</h2></div><p>Želite prispevati metodološki pregled, relevantno gradivo ali sodelovanje pri izvedbi?</p><a class="btn primary" href="{MAIL}">Pišite projektni kontaktni osebi <span aria-hidden="true">↗</span></a></div></section>'''

def team():
 rows=[
 ('2026','GREENCULTLABS','Creative Europe — sodelovanje pri pripravi in oddaji vloge','Prijava oddana; ni referenca ZZT'),
 ('2026','CARESHIFT','CERV — zbiranje profilov, CV-jev in partnerskih podatkov za prijavo','Prijava oddana; ni referenca ZZT'),
 ('2026','GREEN ROOTS YOUTH','Priprava partnerskih povzetkov in delitev projektnih nalog','Projektna prijava; ni potrjene odobritve'),
 ('2026','EKOfeed','Razvoj zasnove in komunikacija s potencialnimi partnerji','Razvoj prijave'),
 ('2026','DCYDE: New Methods of Agro in Croatia','Vodja devetčlanske slovenske skupine, digitalni priročnik','Dokumentirana osebna izvedbena izkušnja'),
 ('2026','DCYDE: Cookbook from Leftovers','Urednik / skrbnik evidenc in prispevkov','Dokumentirana osebna izvedbena izkušnja'),
 ('2026','DCYDE: Youth Survival Guide','Uredništvo in dokumentacija projekta','Dokumentirana osebna izvedbena izkušnja'),
 ('2025','VIBE / The Power Within / The Future We Want','Udeležba na mladinskih izobraževanjih in izmenjavah','Osebna udeležba'),
 ('2025','MEGAPHONE','Udeležba kot predstavnik organizacije Povod','Osebna udeležba'),
 ]
 table=''.join(f'<tr><td>{y}</td><td><strong>{escape(name)}</strong><span>{escape(desc)}</span></td><td>{escape(state)}</td></tr>' for y,name,desc,state in rows)
 return hero('Ekipa in izkušnje','Za projekte stojijo <em>ljudje.</em>','Pravni nosilec novega zavoda in osebne reference njegovih sodelavcev so različne stvari.')+f'''<section class="section"><div class="wrap two-col">{band('Ustanovitelj')}<div><h2>Dan Fredi Grmuša</h2><p class="subtitle">Ustanovitelj · projektna koordinacija · evropske prijave</p><p>Ukvarja se s koordinacijo projektnih nalog, pridobivanjem informacij od partnerskih organizacij, pripravo dokumentacije za evropske prijave, organizacijo mladinskih projektov in digitalno podporo izvedbi.</p><p>Dokumentirane izkušnje vključujejo sodelovanje pri dveh oddanih evropskih prijavah leta 2026, koordinacijo slovenske mladinske skupine v okviru DCYDE in sodelovanje pri mednarodnih izobraževalnih dejavnostih.</p><p>Njegove izkušnje vključujejo pripravo projektnih vlog, koordinacijo mladinskih skupin, sodelovanje s tujimi organizacijami in urejanje digitalnih gradiv. Te kompetence so izhodišče za izvedljiv načrt, ne dokaz že opravljene znanstvene raziskave. Stiki s profesorji in učitelji omogočajo strokovni posvet, niso pa potrjeno partnerstvo ZZT.</p></div></div></section>
 <section class="section cream-section"><div class="wrap"><div class="section-title-row">{band('Osebne reference')}<div><h2>Dokumentirano sodelovanje.</h2><p>Spodaj navedeni projekti niso bili izvedeni s strani ZZT, ustanovljenega leta 2026. Gre za osebne izkušnje predvidenega izvajalca.</p></div></div><div class="table-scroller"><table class="experience-table"><thead><tr><th>Leto</th><th>Projekt in dejanska naloga</th><th>Vrsta reference</th></tr></thead><tbody>{table}</tbody></table></div><p class="note">Podlaga: interna projektna dokumentacija, uradna e-obvestila o oddaji prijav, Erasmus+ komunikacije in evidenca DCYDE. Posamezna dokazila so dostopna ocenjevalcem na upravičeno zahtevo, ne kot javni arhiv zasebne korespondence.</p></div></section>
 <section class="section"><div class="wrap two-col">{band('Upravljanje')}<div><h2>Odgovorna organizacija.</h2><p>Ustanovitelj in glavna kontaktna oseba za projekte je Dan Fredi Grmuša. Pravno zastopanje urejajo ustanovitveni akt in aktualni registrski podatki. Svet zavoda in strokovni svet sta predvidena v aktu; neobjavljenih imenovanj ne predstavljamo kot zasedena mesta.</p>{link('o-zavodu','Pravni podatki <span aria-hidden="true">↗</span>','text-link')}</div></div></section>'''

def cooperation():
 return hero('Sodelovanje','Dober projekt se začne z <em>jasno nalogo.</em>','Povezujemo izvajalce, izobraževalne ustanove in organizacije okoli preverljivih ciljev.')+f'''<section class="section"><div class="wrap two-col">{band('Za koga')}<div><h2>Strokovno sodelovanje brez odvečne administracije.</h2><div class="stack-items"><article><h3>Raziskovalci in univerze</h3><p>Metodološki pregled, analiza podatkov, dostop do strokovne literature in kakovostna interpretacija.</p></article><article><h3>Šole in učitelji</h3><p>Razvoj učnih gradiv, mentorska podpora in praktična okoljska izobraževanja.</p></article><article><h3>Občine in nevladne organizacije</h3><p>Lokalno okoljsko spremljanje, vključevanje javnosti in uporaba rezultatov za odločanje.</p></article><article><h3>Mednarodni projektni partnerji</h3><p>Projektni koncepti, vsebinski prispevki, koordinacija in priprava prijavne dokumentacije.</p></article></div><a class="btn outline" href="{MAIL}">Predlagajte sodelovanje <span aria-hidden="true">↗</span></a></div></div></section><section class="section olive-section"><div class="wrap"><div class="section-title-row">{band('Načelo')}<h2>Partnerstvo potrdimo z dogovorom.</h2></div><p>Pretekli stiki ustanovitelja z organizacijami ne pomenijo, da so te organizacije formalni partnerji ZZT. Na tej strani navajamo možnosti sodelovanja, ne izmišljenih institucionalnih zavez.</p></div></section>'''

def publications():
 sources=[('Joint Research Centre — Guidance on the Monitoring of Marine Litter in European Seas (2023)','https://publications.jrc.ec.europa.eu/repository/handle/JRC133594','Metodologija spremljanja morskih odpadkov'),('Čista obala 2021 — Direkcija RS za vode','https://www.gov.si/novice/2021-09-18-cista-obala-2021/','Pretekli rezultati javne akcije in spremljanja'),('OSPAR — Beach Litter','https://www.ospar.org/work-areas/eiha/marine-litter/assessment-of-marine-litter/beach-litter','Primerljive kategorije in popisni okvir'),('ICOMOS — mednarodne strokovne listine','https://openarchive.icomos.org/','Dokumentiranje grajene dediščine'),('UNECE — Aarhuška konvencija','https://unece.org/environment-policy/public-participation/aarhus-convention/text','Dostop do informacij in vključevanje javnosti'),('OECD — Guidelines for Citizen Participation','https://www.oecd.org/en/publications/2022/09/oecd-guidelines-for-citizen-participation-processes_63b34541.html','Zasnova sodelovanja državljanov')]
 rows=''.join(f'<article class="resource"><div><p class="resource-type">ZUNANJI STROKOVNI VIR</p><h3>{escape(t)}</h3><p>{escape(d)}</p></div>{ext(u,"Odpri vir")}</article>' for t,u,d in sources)
 return hero('Objave in viri','Najprej viri, nato <em>ugotovitve.</em>','Ločujemo lastne bodoče projektne publikacije od raziskav in poročil drugih ustanov.')+f'''<section class="section"><div class="wrap two-col">{band('Publikacije ZZT')}<div><h2>Lastna zbirka je v nastajanju.</h2><p>ZZT kot novoustanovljeni zavod še nima javno objavljene in preverjene lastne raziskovalne publikacije. Ko bodo prve študije zaključene, bomo tukaj objavili metodologijo, rezultate, bibliografijo in pogoje ponovne uporabe.</p></div></div></section><section class="section cream-section"><div class="wrap"><div class="section-title-row">{band('Bibliografija')}<h2>Viri, na katere se opiramo.</h2></div>{rows}</div></section>'''

def contact():
 return hero('Kontakt','Povežimo znanje in <em>izvedbo.</em>','Za strokovna vprašanja, projektne ideje in pobude za sodelovanje uporabite preverjeni projektni kontakt.')+f'''<section class="section"><div class="wrap contact-grid"><div>{eyebrow('Projektni kontakt')}<h2>Pišite ustanovitelju.</h2><p>Kontaktna oseba je ustanovitelj Dan Fredi Grmuša. Pišete mu lahko neposredno na spodnji naslov. Avtomatiziran kontaktni obrazec ni vzpostavljen.</p><a href="mailto:{EMAIL}" class="contact-mail">{EMAIL} <span aria-hidden="true">↗</span></a><p><strong>Kontaktna oseba:</strong> Dan Fredi Grmuša · ustanovitelj</p><p class="note">Povezava odpre vaš e-poštni program. Sporočilo se ne pošlje brez vaše potrditve v e-poštnem odjemalcu.</p></div><div class="contact-address">{eyebrow('Kje delujemo')}<address><strong>ZZT – Zavod za zeleno tehnologijo</strong><br>Kostel · Slovenija</address><hr><h3>O čem se lahko pogovorimo?</h3><p>Okoljski podatki, razvoj izobraževalnih gradiv, dokumentiranje lokalne dediščine ter predlogi za strokovno in mednarodno sodelovanje.</p><p>Za prvi stik zadostuje kratek opis teme in vprašanje, na katero bi želeli odgovoriti.</p><a href="mailto:{EMAIL}" class="text-link">Kontakt: Dan Fredi Grmuša ↗</a></div></div></section>'''

def privacy():
 return hero('Zasebnost','Pregledna spletna <em>izkušnja.</em>','Kaj ta izdaja spletne strani počne in česa ne.')+f'''<section class="section"><div class="wrap two-col">{band('Informacije')}<div><h2>Minimalna obdelava.</h2><p>Spletna stran nima uporabniških računov, lastnih analitičnih skript, sledilnih piškotkov ali spletnega kontaktnega obrazca. Za pošiljanje sporočila uporablja povezavo <code>mailto:</code>, ki odpre vaš e-poštni program.</p><p>Fotografije so izvirno objavljene v zbirki Wikimedia Commons in so ob objavi spletne strani shranjene tudi na gostovanju. Povezavo z Wikimedia vaš brskalnik vzpostavi, če odprete stran z izvirno fotografijo. Gostovanje zagotavlja GitHub Pages, ki lahko obdeluje tehnične podatke o dostopih skladno s svojimi pogoji.</p><p>Upravljavec vsebine je ZZT – Zavod za zeleno tehnologijo. Za zahteve v zvezi z osebnimi podatki pišite ustanovitelju na dan.grmusa@gmail.com. Obvestilo bomo posodobili ob uvedbi novih spletnih funkcij.</p></div></div></section>'''

def credits():
 rows=''.join(f'<tr><td>{escape(p["name"])}</td><td>{escape(p["author"])}</td><td>{escape(p["licence"])}</td><td>{ext(p["url"],"Izvirnik")}</td></tr>' for k,p in PHOTOS.items() if k in ('kolpa_kuzelj','kolpa_bosljiva','kolpa','kostel','izola','ankaran'))
 return hero('Viri fotografij','Fotografije z <em>izvorom.</em>','Dokumentiramo avtorstvo in licence ter ne predstavljamo fotografij kot dokazov lastnih raziskav.')+f'<section class="section"><div class="wrap"><div class="table-scroller"><table class="experience-table"><thead><tr><th>Fotografija</th><th>Avtor</th><th>Licenca</th><th>Izvor</th></tr></thead><tbody>{rows}</tbody></table></div><p class="note">Slike so vizualne upodobitve lokacij; niso fotografije terenskega dela ZZT. Pri fotografijah so navedeni avtorji, oznake licenc in povezave do izvirnikov. Avtorske pravice ostanejo pri avtorjih.</p></div></section>'

PAGES={'':('Domov – ZZT','ZZT s sedežem v Kostelu povezuje okoljske raziskave, zelene tehnologije, izobraževanje mladih in razvoj projektov.',home),
 'o-zavodu':('O zavodu','Uradno poslanstvo, ustanovitveni akt in registracijski podatki ZZT.',about),
 'raziskave-in-razvoj':('Raziskave in razvoj','Raziskovalna področja, metode in okoljski pilotni projekti ZZT.',research),
 'izobrazevanje-in-mladi':('Izobraževanje in mladi','Programi učenja, mladinskega dela in digitalnih kompetenc v ZZT.',education),
 'projekti':('Projekti','Preverljivo stanje projektnih zasnov, prijav in raziskovalnih pobud ZZT.',projects),
 'ekipa-in-izkusnje':('Ekipa in izkušnje','Ustanovitelj ZZT in dokumentirane osebne reference v evropskih in mladinskih projektih.',team),
 'sodelovanje':('Sodelovanje','Strokovno sodelovanje z raziskovalci, izobraževalnimi ustanovami in skupnostmi.',cooperation),
 'publikacije-in-objave':('Publikacije in viri','Raziskovalna literatura, dokumenti in načrtovane publikacije ZZT.',publications),
 'kontakt':('Kontakt','Projektni kontakt in sedež Zavoda za zeleno tehnologijo.',contact),
 'zasebnost':('Zasebnost','Obvestilo o zasebnosti za statično spletno izdajo ZZT.',privacy),
 'viri-fotografij':('Viri fotografij','Avtorji, fotografije in licence vizualnega gradiva spletne strani ZZT.',credits),
}
for p in PROJ:
 PAGES['projekti/'+p['slug']]=(p['title'],p['subtitle'],lambda p=p:project(p))

def layout(slug,title,description,content):
 items=''.join(f'<a href="{url(s)}" aria-current="page" class="active"{("" if slug==s else "")}>{escape(label)}</a>' if slug==s else f'<a href="{url(s)}">{escape(label)}</a>' for s,label in NAV)
 footeritems=''.join(f'<a href="{url(s)}">{escape(l)}</a>' for s,l in NAV if s!='')
 return f'''<!doctype html>
<html lang="sl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#f3f1e9"><title>{escape(title)} | ZZT – Zavod za zeleno tehnologijo</title><meta name="description" content="{escape(description,quote=True)}"><meta name="robots" content="index,follow"><link rel="canonical" href="https://zavod-zzt.eu{url(slug)}"><meta property="og:url" content="https://zavod-zzt.eu{url(slug)}"><meta property="og:type" content="website"><meta property="og:locale" content="sl_SI"><meta property="og:site_name" content="ZZT – Zavod za zeleno tehnologijo"><meta property="og:image" content="https://zavod-zzt.eu/assets/photos/b527e1baf61975f3.jpg"><meta name="twitter:card" content="summary_large_image"><meta property="og:title" content="{escape(title,quote=True)} | ZZT"><meta property="og:description" content="{escape(description,quote=True)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" as="image" href="/assets/photos/b527e1baf61975f3.jpg"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script><script type="application/ld+json">{{"@context":"https://schema.org","@type":"Organization","name":"ZZT – Zavod za zeleno tehnologijo","legalName":"ZZT – Zavod za zeleno tehnologijo, Slavski Laz, zavod za spodbujanje mladih pri novih zelenih tehnologijah","foundingDate":"2026-09-29","url":"https://zavod-zzt.eu/","email":"{EMAIL}","founder":{{"@type":"Person","name":"Dan Fredi Grmuša"}},"address":{{"@type":"PostalAddress","addressLocality":"Kostel","addressCountry":"SI"}}}}</script></head>
<body><a class="skip-link" href="#main">Preskoči na vsebino</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="ZZT – Domov"><span class="brand-symbol" aria-hidden="true">Z<span>.</span></span><span class="brand-name"><strong>ZZT</strong><small>ZAVOD ZA ZELENO TEHNOLOGIJO</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav" aria-label="Odpri navigacijo"><span></span><span></span></button><nav class="main-nav" id="main-nav" aria-label="Glavna navigacija">{items}</nav></div></header>
<main id="main" tabindex="-1">{content}</main><footer class="site-footer"><div class="wrap footer-top"><div><p class="footer-brand">ZZT<span class="dot">.</span></p><p>Zavod za zeleno tehnologijo<br>Kostel · Slovenija</p></div><nav aria-label="Navigacija v nogi">{footeritems}</nav><div><p class="footer-kicker">Ustanovitelj in kontakt</p><strong class="footer-person">Dan Fredi Grmuša</strong><a href="mailto:{EMAIL}">{EMAIL} ↗</a><p>Raziskovanje · izobraževanje · sodelovanje</p></div></div><div class="wrap footer-bottom"><span>© 2026 ZZT – Zavod za zeleno tehnologijo</span><span><a href="/zasebnost/">Zasebnost</a> · <a href="/viri-fotografij/">Viri fotografij</a></span><span>Kostel · Slovenija</span></div></footer></body></html>'''

for slug,(title,desc,fn) in PAGES.items():
 dest=OUT/slug/'index.html' if slug else OUT/'index.html'
 dest.parent.mkdir(parents=True,exist_ok=True)
 dest.write_text(layout(slug,title,desc,fn()),encoding='utf-8')
# Keep machine-readable content model for verification/future CMS migration.
(OUT/'assets'/'projects.json').write_text(json.dumps([{k:v for k,v in p.items() if k!='photo'} for p in PROJ],ensure_ascii=False,indent=2),encoding='utf-8')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://zavod-zzt.eu/sitemap.xml\n',encoding='utf-8')
(OUT/'CNAME').write_text('zavod-zzt.eu\n',encoding='utf-8')
(OUT/'.nojekyll').touch()
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + ''.join('<url><loc>https://zavod-zzt.eu'+url(slug)+'</loc></url>\n' for slug in PAGES) + '</urlset>\n',encoding='utf-8')
(OUT/'404.html').write_text(layout('404','Strani ni mogoče najti','Stran ni na voljo.',f'<section class="section"><div class="wrap"><h1>Strani ni mogoče najti.</h1><p>Naslov ni pravilen ali pa je bila vsebina premaknjena.</p>{link("","Nazaj na naslovnico","btn primary")}</div></section>'),encoding='utf-8')
print('Created',len(PAGES),'pages at',OUT)
